"""Record the exact standalone V19 artifact after sequential native checks."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[2];base=root/'output/elyndor/pixellab-v19'
def read(name):return json.loads((base/name).read_text(encoding='utf-8'))
a=json.loads((root/'output/elyndor/continuous-standalone-audit.json').read_text());reg=read('regression.json');revision=read('revision/report.json');coached=read('coached/report.json');campaign=read('campaign/report.json');performance=read('performance/native.json');combat=read('combat-profile-final.json');atlas=read('atlas-performance.json');voices=read('audio-audit.json');sounds=read('soundtrack-audit.json');water=read('water/report.json');locations=read('locations/report.json');macro=read('overworld/report.json')
sha=hashlib.sha256((root/'index.html').read_bytes()).hexdigest()
assert sha==reg['sha256']==a['sha256'] and a['sourceMatchesArtifact'] and not a['cropWarnings']
assert len(reg['checks'])==27 and all(q['pass']for q in reg['checks'])
assert all(q['pass']for q in [revision,coached,atlas,voices,sounds,water,locations,macro])
assert campaign['campaign']['final']=='complete' and not campaign['errors'] and not campaign['voiceMissing']
assert not combat['newPrograms'] and combat['cpu']['p95']<25
pump=read('pump-fixed.json');assert not pump['errors'] and not pump['newPrograms'] and pump['tick']['p95']<10 and pump['tick']['max']<50
transcripts=json.loads((root/'elyndor/audio/transcription-audit-v18.json').read_text());assert transcripts['clips']==10 and not transcripts['unresolvedWordDifferences']
r={'release':'elyndor-2026-10-29-solid-stairs-current-title-records-v19','game':'The Last Light of Elyndor','artifact':{'file':'index.html','bytes':a['bytes'],'sha256':sha,'offline':True},
 'changes':['Four terrace stairways use solid textured foundations instead of open sky below their lower treads; the steep lower approach has nine additional treads','Rendered stair and landing geometry shares the same height queries as feet and navigation','Western starting-bridge approach follows the actual curved road, fading paving into earth with the same world-space material','920 GPU-animated world-space foam streamlines move downstream from the gate, over cascades and through the lower stream; release shaders warm during loading','Removed the obsolete broad surface sheet and reject uninitialised or out-of-frame projective reflection samples','Title navigation is on the left; a versioned changelog and three journey cards occupy the right panel','Eight live POI views cycle in a shuffled nonrepeating bag, with the full main cast and gameplay markers hidden; NPCs and environment continue animating','Three manual slots support metadata and party previews, loading, saving at inn circles, overwrite confirmation, deletion confirmation and unreadable-record cleanup','Background changes pause while browsing records; save actions cannot race scene rebuilds; legacy records, automatic inn checkpoints and preferences remain supported'],
 'art':{'generator':'PixelLab','nativeSelectedFamilies':41,'runtimeFamilies':42,'packedSpritePoses':a['packedPoses'],'sourceCropWarnings':0,'newNativeMaterialPages':0,'materialSize':[512,512],'rejectedCandidatesExcluded':True},
 'audio':{'provider':'ElevenLabs','recordedVoices':voices['clips'],'soundAssets':sounds['sounds'],'newNarration':0,'newSoundEffects':0,'offline':True,'embeddedCredential':False,'transcription':transcripts},
 'validation':{'checks':reg['checks'],'revisionFeatures':revision,'coachedBattleRegression':coached,'stairFloorMaxGapMetres':max(q['gap']for q in revision['steps']),'locations':locations,'sourceMatchesArtifact':True,'storyProgressionSteps':len(campaign['campaign']['log']),'storyBattles':len(campaign['campaign']['battles']),'restoredLights':len(campaign['campaign']['restored']),'saveLoad':campaign['persistence'],'waterJoinMaxGapMetres':max(j['gap']for row in coached['water']for j in row['joins']),'overworldApproaches':macro},
 'performance':{'device':performance['device'],'nativeScenarios':performance['scenarios'],'pump':read('pump-fixed.json'),'tutorial':read('onboarding-performance.json'),'combatRenderCPU':combat['cpu'],'newCombatPrograms':len(combat['newPrograms']),'atlas':atlas,'scope':'Native Chrome on the recorded test GPU; performance varies by hardware.'}}
(root/'release.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(json.dumps({'release':r['release'],'bytes':a['bytes'],'sha256':sha,'checks':len(reg['checks']),'audioAssets':voices['clips']+sounds['sounds']}))
